mapper.select:
SELECT id AS id, cashier_id AS cashierId, cashier_name AS cashierName, counter_no AS counterNo, start_time AS startTime, end_time AS endTime, order_count AS orderCount, sales_amount AS salesAmount, cash_amount AS cashAmount, bank_amount AS bankAmount, mobile_amount AS mobileAmount, balance_amount AS balanceAmount, return_amount AS returnAmount, expected_cash AS expectedCash, status AS status FROM cashier_shift
AND cashier_name LIKE CONCAT('%', #{q.cashierName}, '%')
AND counter_no = #{q.counterNo}
AND status = #{q.status}
AND cashier_id = #{q.cashierId}
AND start_time >= CONCAT(#{q.beginDate}, ' 00:00:00')
AND start_time <= CONCAT(#{q.endDate}, ' 23:59:59')
ORDER BY start_time DESC, id DESC
